<?php
require __DIR__.'/inc/v11.php';auth();v11_require();require_once __DIR__.'/inc/permissions.php';require_once __DIR__.'/inc/moving-file.php';
if($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);header('Allow: GET');exit('Bu dosya yalnız görüntüleme içindir.');}
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);$file=null;$error='';$admin=in_array(ek_user_role(),['admin','administrator'],true);
try{if(!$id||$id<1)throw new RuntimeException('Geçerli bir taşınma dosyası seçin.');$file=ekMovingFile(db(),$id,$admin);}catch(Throwable $e){http_response_code(409);error_log('Moving file: '.$e->getMessage());$error=$e instanceof PDOException?'Taşınma dosyası okunamadı. Kayıtlarınız korunuyor.':$e->getMessage();}
require __DIR__.'/inc/layout.php';top('Taşınma Dosyası');
?>
<link rel="stylesheet" href="assets/v11.css?v=36001"><div class="v11-head"><h1>Taşınma Dosyası</h1><p>Güncel teklif, mevcut operasyon planı ve ilgili belgeler.</p><a href="moving-files.php">Dosya listesine dön</a></div>
