<section class="v11-card"><h2>TD-<?=str_pad((string)$ctx['root_id'],6,'0',STR_PAD_LEFT)?> · <?=h($q['name'])?></h2><p>Geçerli teklif: <a href="view.php?id=<?=(int)$ctx['effective_id']?>"><?=h($q['quote_no'])?></a></p><dl><dt>Çıkış adresi</dt><dd><?=h($q['origin'])?></dd><dt>Varış adresi</dt><dd><?=h($q['destination'])?></dd><dt>Teklif hacmi</dt><dd><?=h(number_format((float)$q['volume'],2,',','.'))?> m³</dd><dt>Hizmetler</dt><dd><?=h(is_array($services)?implode(', ',array_filter($services,'is_string')):'')?></dd></dl>
